create or replace function public.get_private_event_preview(p_event_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare e public.events; me uuid:=public.current_profile_id(); allowed boolean:=false; begin select * into e from public.events where id=p_event_id and visibility='private'; if e.id is null then return null; end if; allowed:=me is not null and(e.owner_user_id=me or exists(select 1 from public.event_invites i where i.event_id=e.id and i.invitee_user_id=me and i.status in('pending','accepted')) or exists(select 1 from public.entries en where en.event_id=e.id and en.signup_user_id=me and en.status<>'withdrawn')); return jsonb_build_object('id',e.id,'name',e.name,'visibility',e.visibility,'status',case when e.status='signup' and not public.event_registration_open(e) then 'locked' else e.status end,'match_type',e.match_type,'format',e.format,'suggested_level_min',e.suggested_level_min,'suggested_level_max',e.suggested_level_max,'city',e.city,'can_view_full',allowed); end $$;
create or replace function public.list_events(p_mine boolean default false,p_filters jsonb default '{}'::jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare result jsonb; begin if p_mine and public.current_profile_id() is null then raise exception 'AUTH_REQUIRED'; end if; select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) into result from(select e.id,e.name,case when p_mine or e.visibility='public' then e.owner_user_id else null end owner_user_id,case when e.status='signup' and not public.event_registration_open(e) then 'locked' else e.status end status,e.visibility,e.match_type,e.format,e.suggested_level_min,e.suggested_level_max,e.city,case when p_mine or e.visibility='public' then e.event_date else null end event_date,case when p_mine or e.visibility='public' then e.event_time else null end event_time,case when p_mine or e.visibility='public' then e.registration_deadline else null end registration_deadline,case when p_mine or e.visibility='public' then e.venue else null end venue,case when p_mine or e.visibility='public' then e.best_of else null end best_of,case when p_mine or e.visibility='public' then e.entry_limit else null end entry_limit,case when p_mine or e.visibility='public' then e.fee_type else null end fee_type,case when p_mine or e.visibility='public' then e.fixed_fee_per_entry else null end fixed_fee_per_entry,case when p_mine or e.visibility='public' then e.venue_fee_total else null end venue_fee_total,case when p_mine or e.visibility='public' then e.ball_fee_total else null end ball_fee_total,case when p_mine or e.visibility='public' then e.other_fee_total else null end other_fee_total,case when p_mine or e.visibility='public' then owner.nickname else null end owner_nickname,case when p_mine or e.visibility='public' then owner.avatar_url else null end owner_avatar_url,case when p_mine or e.visibility='public' then(select count(*) from public.entries en where en.event_id=e.id and en.status='confirmed') else null end confirmed_count,case when p_mine or e.visibility='public' then(select count(*) from public.entries en where en.event_id=e.id and en.status='waitlist') else null end waitlist_count from public.events e join public.profiles owner on owner.id=e.owner_user_id where(case when p_mine then case when p_filters->>'scope'='joined' then exists(select 1 from public.entries own_entry where own_entry.event_id=e.id and own_entry.signup_user_id=public.current_profile_id() and own_entry.status!='withdrawn') else e.owner_user_id=public.current_profile_id() end else e.status!='finished' end) and(coalesce(p_filters->>'match_type','')='' or e.match_type=p_filters->>'match_type') and(coalesce(p_filters->>'event_date','')='' or(e.visibility='public' and e.event_date::text=p_filters->>'event_date')) and(coalesce(p_filters->>'status','')='' or(case when e.status='signup' and not public.event_registration_open(e) then 'locked' else e.status end)=p_filters->>'status') order by e.event_date asc nulls last,e.created_at desc,e.id limit 200)t; return result; end $$;
create or replace function public.list_my_event_invites() returns jsonb language sql security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'event_id',i.event_id,'event_name',e.name,'event_date',e.event_date,'event_time',e.event_time,'registration_deadline',e.registration_deadline,'city',e.city,'venue',e.venue,'suggested_level_min',e.suggested_level_min,'suggested_level_max',e.suggested_level_max,'match_type',e.match_type,'invite_kind',i.invite_kind,'inviter_user_id',i.inviter_user_id,'inviter_nickname',p.nickname,'status',i.status,'registration_open',public.event_registration_open(e),'created_at',i.created_at) order by(i.status='pending') desc,i.created_at desc),'[]'::jsonb) from public.event_invites i join public.events e on e.id=i.event_id join public.profiles p on p.id=i.inviter_user_id where i.invitee_user_id=public.current_profile_id() $$;